guidance.correct_example:
import threading

class SafeList:
    def __init__(self):
        self._items: list[str] = []
        self._lock = threading.Lock()

    def add(self, a_item: str) -> Result[None]:
        with self._lock:
            self._items.append(a_item)
            return Result.success(None)

